def _aplicar(desde: int, hasta: int) -> None:
    conn = op.get_bind()
    for archivo, contenidos in CAMBIOS.items():
        resultado = conn.execute(
            sa.text(
                "UPDATE route_server_templates SET content = :nuevo, updated_at = now() "
                "WHERE filename = :archivo AND content = :anterior"
            ),
            {"nuevo": contenidos[hasta], "archivo": archivo,
             "anterior": contenidos[desde]},
        )
        total = conn.execute(
            sa.text("SELECT count(*) FROM route_server_templates WHERE filename = :archivo"),
            {"archivo": archivo},
        ).scalar_one()
        sin_tocar = total - resultado.rowcount
        if sin_tocar:
            print(
                f"aviso: {sin_tocar} de {total} plantillas {archivo} estaban "
                "editadas y quedaron como estaban"
            )


def upgrade() -> None:
    _aplicar(0, 1)
    op.drop_column("route_servers", "rpki_policy")
    op.execute("DROP TYPE IF EXISTS rpki_policy")


def downgrade() -> None:
    op.execute(
        "CREATE TYPE rpki_policy AS ENUM ('info_only', 'reject_invalid')"
    )
    op.add_column(
        "route_servers",
        sa.Column(
            "rpki_policy",
            sa.Enum("info_only", "reject_invalid", name="rpki_policy"),
            nullable=False,
            server_default="info_only",
        ),
    )
    _aplicar(1, 0)
